import gzip,collections,re,json
sets={'dnase2018':['ENCFF876DOW','ENCFF764MOY'],'dnase2020_fdr005':['ENCFF530GZW','ENCFF350XAH'],'dnase2020_fdr0001':['ENCFF812QOW','ENCFF407NXV'],'hotspots2018':['ENCFF855TSQ','ENCFF519XYN']}
