import numpy as np,pandas as pd,glob,gzip,collections,os,json

def load_regions(path):
 out={}
 x=pd.read_csv(path,sep='\\t',header=None,usecols=[0,1,2])
 for c,g in x.groupby(0):
  a=g[[1,2]].sort_values(1).to_numpy();merged=[]
  for s,e in a:
   if merged and s<=merged[-1][1]:merged[-1][1]=max(e,merged[-1][1])
   else:merged.append([s,e])
  out[c]=np.array(merged)
 return out

def overlap(df,regions,start='start',end='end'):
 hit=np.zeros(len(df),dtype=bool)
 for c,g in df.groupby('chrom'):
  a=regions.get(c)
  if a is None:continue
  hit[g.index]=np.searchsorted(a[:,0],g[end],side='left')>np.searchsorted(a[:,1],g[start],side='right')
 return hit

black=load_regions('downloads/hg38-blacklist.v2.bed.gz')
regions={os.path.basename(p).replace('.bed',''):load_regions(p) for p in glob.glob('analysis/dnase*.bed')+glob.glob('analysis/hotspots*.bed')}
rows=[]
for path in sorted(glob.glob('analysis/peaks/*_peaks.narrowPeak')):
 name=os.path.basename(path).split('_')[0]
 x=pd.read_csv(path,sep='\\t',header=None,names=['chrom','start','end','name','score','strand','fold','p','q','offset'])
 x=x[~overlap(x,black)].reset_index(drop=True)
 x['summit']=x.start+x.offset;x['sstart']=x.summit-100;x['send']=x.summit+101
 for rn,reg in regions.items():
  x[rn+'_open']=overlap(x,reg)
  x[rn+'_summit_open']=overlap(x,reg,'sstart','send')
 x.sort_values('p',ascending=False).to_csv(f'analysis/{name}.annotated.tsv',sep='\\t',index=False)
 for n in [0,1000,5000,10000]:
  y=x.sort_values('p',ascending=False).head(n) if n else x
  row={'TF':name,'top_n':n,'n_peaks':len(y),'median_fold':y.fold.median(),'median_q':y.q.median()}
  for rn in regions:
   closed=~y[rn+'_open']
   row[rn+'_closed_n']=int(closed.sum());row[rn+'_closed_fraction']=float(closed.mean())
   row[rn+'_closed_fold_weight']=float(y.loc[closed,'fold'].sum()/y.fold.sum())
  rows.append(row)
res=pd.DataFrame(rows)
res.to_csv('analysis/peak_summary.tsv',sep='\\t',index=False)
print(res[['TF','top_n','n_peaks','median_fold','dnase2020_fdr005_closed_fraction','hotspots2018_closed_fraction']].to_string(index=False))
